CREATE TYPE "PaymentStatus" AS ENUM ('CREATED','PENDING','AUTHORIZED','CAPTURED','FAILED','CANCELLED','REFUNDED'); CREATE TYPE "InvoiceStatus" AS ENUM ('DRAFT','ISSUED','PAID','VOID'); CREATE TABLE "Payment" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"bookingId" UUID NOT NULL REFERENCES "Booking"("id") ON DELETE RESTRICT,"accountId" UUID NOT NULL REFERENCES "Account"("id") ON DELETE RESTRICT,"amountMinor" INTEGER NOT NULL CHECK ("amountMinor">0),"currency" TEXT NOT NULL DEFAULT 'SAR',"status" "PaymentStatus" NOT NULL DEFAULT 'CREATED',"idempotencyKey" TEXT NOT NULL UNIQUE,"providerReference" TEXT UNIQUE,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE "Invoice" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"paymentId" UUID NOT NULL UNIQUE REFERENCES "Payment"("id") ON DELETE RESTRICT,"number" TEXT NOT NULL UNIQUE,"status" "InvoiceStatus" NOT NULL DEFAULT 'DRAFT',"issuedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX "Payment_accountId_status_idx" ON "Payment" ("accountId","status");